namespace InventoryTracker.Api.Domain;

/// <summary>
/// A unit that items are measured in, for example "kg" or "Bag" (US-06). Table <c>Units</c>.
/// </summary>
/// <remarks>
/// This is an EF Core <em>entity</em>: a plain C# class whose instances are rows in a table. EF Core reads and
/// writes its public properties as columns. The table rules (lengths, indexes) are not written here but in
/// <c>Data/Configurations/UnitOfMeasureConfiguration.cs</c>, so the domain classes stay free of database code.
/// </remarks>
public class UnitOfMeasure
{
    /// <summary>Primary key, generated by the database.</summary>
    public int Id { get; set; }

    /// <summary>AC-06.1: the name as entered, trimmed, 1 to 50 characters.</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>
    /// AC-06.2: <see cref="Name"/> trimmed and upper-cased (see <see cref="NameNormalizer"/>). A unique index on
    /// this column makes "kg" and "KG" count as the same name, so the database itself refuses a duplicate.
    /// </summary>
    public string NameNormalized { get; set; } = string.Empty;
}
